73	// validateAndReplay 校验全部成功记录并从冻结的初始余额重放结算与退款：
74	// ID 唯一、序列连续、费用一致、int64 不溢出、退款只能引用此前存在的结算且
75	// 每笔结算最多退回一次、退款金额必须等于原扣款、任一时点余额非负，
76	// 且重放结果必须等于文件中的最终余额。任何不符都判定账本损坏。
77	//
78	// 结算与退款按各自成功历史交错：退款 r 只允许发生在序号 <= r.AfterSeq 的
79	// 结算之后（AfterSeq 是退款落账时结算历史的长度）。这保留了
80	// “付款 → 退款 → 再付款”的真实时间顺序，使中间余额与最终余额都可验证。
81	func validateAndReplay(initial, final map[balanceKey]int64, records []Record, refunds []RefundRecord) error {
82		// 先校验结算自身的结构不变式（余额相关的判定由后面的交错重放完成，
83		// 因为退款回收的余额允许同一笔钱被再次扣出，累计毛扣款可能超过初始余额）。
84		seen := map[string]bool{}
85		for i, r := range records {
86			if r.ID == "" {
87				return ledgerError(ErrCorrupt, "settlement %d has empty id", i)
88			}
89			if seen[r.ID] {
90				return ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
91			}
92			seen[r.ID] = true
93			if r.Account == "" || r.Asset == "" {
94				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
95			}
96			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
97				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
98			}
99			if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
100				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
101			}
102			if r.FeeBps < 0 || r.FeeBps > 10000 {
103				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
104			}
105			if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
106				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
107			}
108			if r.Charged != r.Amount+r.Fee {
109				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
110			}
111			if int64(i)+1 != r.Seq {
112				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
113			}
114		}
115	
116		// 校验退款自身的不变式：字段非空、序列连续、引用的结算在退款时点已存在、
117		// 金额与去向与原结算逐字一致、每笔结算最多退回一次、退款编号全局唯一。
118		// 此外付款历史只会追加，因此按退款成功顺序（即记录顺序）看，after_seq
119		// 必须单调不减：后一笔退款落账时，已存在的结算不可能比前一笔退款时更少。
120		// 该规则针对整本账本的结算历史，与退款属于哪个账户、资产或引用哪笔付款无关。
121		seenRefund := map[string]bool{}
122		refundedBy := map[string]string{} // 结算编号 -> 首个退回它的退款编号
123		prevAfterSeq := int64(-1)
124		prevRefundID := ""
125		for i, rf := range refunds {
126			if rf.ID == "" {
127				return ledgerError(ErrCorrupt, "refund %d has empty id", i)
128			}
129			if seenRefund[rf.ID] {
130				return ledgerError(ErrCorrupt, "duplicate refund id %q", rf.ID)
131			}
132			seenRefund[rf.ID] = true
133			if rf.SettlementID == "" || rf.Reason == "" {
134				return ledgerError(ErrCorrupt, "refund %q missing settlement_id or reason", rf.ID)
135			}
136			if int64(i)+1 != rf.Seq {
137				return ledgerError(ErrCorrupt, "refund %q sequence gap", rf.ID)
138			}
139			if rf.AfterSeq < 0 || rf.AfterSeq > int64(len(records)) {
140				return ledgerError(ErrCorrupt, "refund %q references settlement outside history (after_seq=%d)", rf.ID, rf.AfterSeq)
141			}
142			if rf.AfterSeq < prevAfterSeq {
143				return ledgerError(ErrCorrupt,
144					"refund %q (seq %d) has after_seq %d, but previous refund %q (seq %d) already saw %d settlements: payment history only grows",
145					rf.ID, rf.Seq, rf.AfterSeq, prevRefundID, int64(i), prevAfterSeq)
146			}
147			prevAfterSeq = rf.AfterSeq
148			prevRefundID = rf.ID
149			var target *Record
150			for j := range records {
151				if records[j].Seq <= rf.AfterSeq && records[j].ID == rf.SettlementID {
152					target = &records[j]
153					break
154				}
155			}
156			if target == nil {
157				return ledgerError(ErrCorrupt, "refund %q references non-existent settlement %q", rf.ID, rf.SettlementID)
158			}
159			if rf.Account != target.Account || rf.Asset != target.Asset ||
160				rf.Amount != target.Amount || rf.Fee != target.Fee || rf.Charged != target.Charged {
161				return ledgerError(ErrCorrupt, "refund %q amount or destination differs from settlement %q", rf.ID, rf.SettlementID)
162			}
163			if rf.Charged <= 0 {
164				return ledgerError(ErrCorrupt, "refund %q has non-positive charged amount", rf.ID)
165			}
166			if other, dup := refundedBy[rf.SettlementID]; dup {
167				return ledgerError(ErrCorrupt, "settlement %q refunded twice: %q and %q", rf.SettlementID, other, rf.ID)
168			}
169			refundedBy[rf.SettlementID] = rf.ID
170		}
171	
172		// 按成功时间交错重放：第 s 笔结算之后落入 after_seq==s 的全部退款
173		// （退款之间按其自身序号；用分桶而非假定 after_seq 单调，以抵抗篡改数据）。
174		// net[k] 为该组合截至当前时点的“净扣款”（扣款增加、退款减少），
175		// 必须始终落在 [0, initial]，且不发生 int64 溢出。
176		buckets := make([][]int, len(records)+1) // after_seq -> refunds 下标
177		for i := range refunds {
178			buckets[refunds[i].AfterSeq] = append(buckets[refunds[i].AfterSeq], i)
179		}
180		net := make(map[balanceKey]int64)
181		for s := range records {
182			r := &records[s]
183			k := balanceKey{r.Account, r.Asset}
184			sum := net[k]
185			if r.Charged > math.MaxInt64-sum {
186				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
187			}
188			sum += r.Charged
189			if sum > initial[k] {
190				return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative during replay", r.ID, r.Account, r.Asset)
191			}
192			net[k] = sum
193	
194			for _, ri := range buckets[int64(s)+1] {
195				rf := &refunds[ri]
196				rk := balanceKey{rf.Account, rf.Asset}
197				cur := net[rk]
198				if rf.Charged > cur {
199					return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
200				}
201				net[rk] = cur - rf.Charged
202			}
203		}
204		// after_seq==0 的退款不可能引用任何已存在结算，前面理应已拒绝；
205		// 此处兜底，任何未被消费的退款都视为顺序损坏。
206		if len(buckets[0]) != 0 {
207			return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
208		}
209	
210		// 交错重放后的末态必须与文件中的最终余额逐组合一致。
211		for k, start := range initial {
212			got := start - net[k]
213			if want, present := final[k]; !present || got != want {
214				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
215			}
216		}
217		for k := range final {
218			if _, ok := initial[k]; !ok {
219				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
220			}
221		}
222		return nil
223	}
224	
225	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
226	func checksumHex(data []byte) string {
227		sum := sha256.Sum256(data)
228		return hex.EncodeToString(sum[:])
229	}
