1038		if rr.Results[0].Status != StatusNotFound || rr.Results[1].Status != StatusNotFound {
1039			t.Fatalf("want not_found for missing/failed, got %+v", rr.Results)
1040		}
1041		if rr.Results[2].Status != StatusRefundSuccess {
1042			t.Fatalf("valid refund: %+v", rr.Results[2])
1043		}
1044		balAfter, _ := l.Balance("aa", "usdc") // 100-30+30 = 100
1045	
1046		// 新退款编号指向已退款结算：already_refunded，不加余额。
