189	func TestCLIRefundLifecycle(t *testing.T) {
190		ledgerPath := t.TempDir() + "/ledger.json"
191	
192		if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
193			`{"balances":[{"account":"aa-1","asset":"usdc","balance":2000}]}`); r.code != 0 {
194			t.Fatalf("init: %s", r.err)
195		}
196		// p1 成功（charged 1504），p2 余额不足失败。
197		batch := `{"fee_bps":30,"intents":[
198		  {"id":"p1","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1500,"nonce":1},
199		  {"id":"p2","account":"aa-1","asset":"usdc","amount":900}
200		]}`
201		if r := runCLIWith(t, []string{"submit", "-l", ledgerPath}, batch); r.code != 0 {
202			t.Fatalf("submit: %s", r.err)
203		}
204	
205		// 退款批次：成功 / 重复 / 冲突 / 已退款 / 目标不存在 / 参数非法，逐项返回且退出码 0。
206		refunds := `{"refunds":[
207		  {"id":"r1","settlement_id":"p1","reason":"cancel"},
208		  {"id":"r1","settlement_id":"p1","reason":"cancel"},
209		  {"id":"r1","settlement_id":"p1","reason":"changed"},
210		  {"id":"r2","settlement_id":"p1","reason":"again"},
211		  {"id":"r3","settlement_id":"ghost","reason":"x"},
212		  {"id":"r4","settlement_id":"p2","reason":"x"},
213		  {"id":"","settlement_id":"p1","reason":"x"}
214		]}`
215		r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, refunds)
216		if r.code != 0 {
217			t.Fatalf("refund batch must exit 0 even with per-item failures: %s", r.err)
218		}
219		var res struct {
220			Results []struct {
221				ID           string `json:"id"`
222				Status       string `json:"status"`
223				SettlementID string `json:"settlement_id"`
224				Account      string `json:"account"`
225				Asset        string `json:"asset"`
226				Charged      int64  `json:"charged"`
227			} `json:"results"`
228		}
229		if err := json.Unmarshal([]byte(r.out), &res); err != nil {
230			t.Fatal(err)
231		}
232		want := []string{"refunded", "duplicate", "conflict", "already_refunded", "not_found", "not_found", "invalid_parameter"}
233		if len(res.Results) != len(want) {
234			t.Fatalf("got %d results, want %d: %s", len(res.Results), len(want), r.out)
235		}
236		for i, x := range res.Results {
237			if x.Status != want[i] {
238				t.Fatalf("item %d status=%s want %s", i, x.Status, want[i])
239			}
240		}
241		// 成功与重复必须回传原付款编号、账户、资产、总额。
242		for _, i := range []int{0, 1} {
243			x := res.Results[i]
244			if x.SettlementID != "p1" || x.Account != "aa-1" || x.Asset != "usdc" || x.Charged != 1504 {
245				t.Fatalf("item %d missing trace fields: %+v", i, x)
246			}
247		}
248	
249		// 退款后余额恢复为 2000（全额含手续费）。
250		r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
251		var snap struct {
252			Balances []struct {
253				Balance int64 `json:"balance"`
254			} `json:"balances"`
255			Refunds []struct {
256				ID           string `json:"id"`
257				SettlementID string `json:"settlement_id"`
258				Reason       string `json:"reason"`
259				Charged      int64  `json:"charged"`
260			} `json:"refunds"`
261		}
262		if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
263			t.Fatal(err)
264		}
265		if len(snap.Balances) != 1 || snap.Balances[0].Balance != 2000 {
266			t.Fatalf("balance after refund=%+v", snap.Balances)
267		}
268		if len(snap.Refunds) != 1 || snap.Refunds[0].SettlementID != "p1" || snap.Refunds[0].Charged != 1504 {
269			t.Fatalf("query refunds=%+v", snap.Refunds)
270		}
271	
272		// 空列表返回空结果。
273		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{"refunds":[]}`); r.code != 0 ||
274			strings.TrimSpace(r.out) != "{\n  \"results\": []\n}" {
275			t.Fatalf("empty refund batch: code=%d out=%q err=%s", r.code, r.out, r.err)
276		}
277	
278		// 非法 JSON 走批次级错误信封。
279		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{bad`); r.code != 1 ||
280			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
281			t.Fatalf("bad refund json: code=%d err=%s", r.code, r.err)
282		}
283	
284		// 缺少 -l。
